import type { ButtonHTMLAttributes } from "react";
import { cn } from "@/shared/ui/cn";

type ButtonVariant = "primary" | "secondary" | "outline" | "ghost";
type ButtonSize = "sm" | "md" | "lg";

type ButtonStyleOptions = {
  variant?: ButtonVariant;
  size?: ButtonSize;
  className?: string;
};

export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: ButtonVariant;
  size?: ButtonSize;
  isLoading?: boolean;
}

const variantClasses: Record<ButtonVariant, string> = {
  primary:
    "bg-brand-teal text-white shadow-sm hover:bg-[#004d51] focus-visible:ring-brand-teal",
  secondary:
    "bg-white text-brand-teal ring-1 ring-brand-teal/20 hover:bg-brand-mint/35 focus-visible:ring-brand-teal",
  outline:
    "border border-brand-teal text-brand-teal hover:bg-brand-teal/5 focus-visible:ring-brand-teal",
  ghost:
    "text-brand-teal hover:bg-brand-teal/5 focus-visible:ring-brand-teal",
};

const sizeClasses: Record<ButtonSize, string> = {
  sm: "min-h-10 px-4 text-sm",
  md: "min-h-11 px-6 text-sm",
  lg: "min-h-12 px-7 text-base",
};

export function buttonClassName({
  variant = "primary",
  size = "md",
  className,
}: ButtonStyleOptions = {}) {
  return cn(
    "inline-flex items-center justify-center rounded-full font-semibold transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-55",
    variantClasses[variant],
    sizeClasses[size],
    className,
  );
}

export function Button({
  children,
  variant = "primary",
  size = "md",
  isLoading = false,
  disabled,
  className,
  type = "button",
  ...props
}: ButtonProps) {
  return (
    <button
      type={type}
      className={buttonClassName({ variant, size, className })}
      disabled={disabled || isLoading}
      aria-busy={isLoading || undefined}
      {...props}
    >
      {isLoading ? "Procesando..." : children}
    </button>
  );
}

export default Button;
